// Generated by `npx @musikhood-dev/auth-client init` — this file is yours, edit freely.
import { useState, type FormEvent } from 'react'
import { useAuth, useMfa } from '@musikhood-dev/auth-client/react'

import { Button } from '@@/components/ui/button'
import { Input } from '@@/components/ui/input'
import { Label } from '@@/components/ui/label'
import { MfaCodeForm, type MfaCodeSubmit } from '@@/components/auth/mfa-code-form'
import { isAuthError, loginErrorMessage, MFA_TEXTS, mfaErrorMessage } from '@@/lib/mfa'

// Login form with the 2FA code step. Render it inside <AuthBoundary mode="guest"> —
// after a successful login the package redirects to `homePath` by itself.
export function LoginForm() {
  const { login } = useAuth()
  const mfa = useMfa()

  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  // Inline message under the password form (bad password, 429 limit, expired 2FA step).
  const [formError, setFormError] = useState<string | null>(null)
  const [mfaError, setMfaError] = useState<string | null>(null)

  async function handleLogin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setFormError(null)
    setMfaError(null)
    try {
      await login({ username, password })
    } catch (error) {
      // 401 mfa_required → mfa.stage === 'code': the code step renders below by itself.
      if (isAuthError(error, 'MfaRequiredError')) return
      if (isAuthError(error, 'MfaEnrollmentRequiredError')) {
        // The panel requires 2FA and the user has none: full navigation to the setup page.
        if (error.enrollmentUrl) window.location.assign(error.enrollmentUrl)
        else setFormError(MFA_TEXTS.enrollmentFailed)
        return
      }
      setFormError(loginErrorMessage(error))
    }
  }

  async function handleMfaSubmit(data: MfaCodeSubmit) {
    setMfaError(null)
    try {
      await mfa.verify(data)
    } catch (error) {
      if (isAuthError(error, 'MfaTokenExpiredError')) {
        // auth-client already returned to the password step (stage idle).
        setFormError(MFA_TEXTS.tokenExpired)
        return
      }
      setMfaError(mfaErrorMessage(error) ?? MFA_TEXTS.verifyFailed)
    }
  }

  if (mfa.stage === 'code') {
    return (
      <div className="space-y-4">
        <p className="text-sm text-muted-foreground">Wpisz kod weryfikacji dwuetapowej</p>
        <MfaCodeForm
          isPending={mfa.verify.isPending}
          error={mfaError}
          submitLabel="Zweryfikuj"
          onSubmit={(data) => void handleMfaSubmit(data)}
          onCancel={() => {
            setMfaError(null)
            mfa.reset()
          }}
          cancelLabel="Wróć do logowania"
        />
      </div>
    )
  }

  return (
    <form onSubmit={(e) => void handleLogin(e)} className="space-y-5">
      <div className="space-y-2">
        <Label htmlFor="login-username">Email</Label>
        <Input
          id="login-username"
          type="email"
          autoComplete="username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
        />
      </div>
      <div className="space-y-2">
        <Label htmlFor="login-password">Hasło</Label>
        <Input
          id="login-password"
          type="password"
          autoComplete="current-password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
      </div>
      {formError ? <p className="text-sm text-destructive">{formError}</p> : null}
      <Button type="submit" className="w-full" size="lg" disabled={login.isPending}>
        {login.isPending ? 'Logowanie…' : 'Zaloguj się'}
      </Button>
    </form>
  )
}
